create table cart (total_amount numeric(38,2), customer_id bigint, id bigint generated by default as identity, restaurant_id bigint, primary key (id));
create table cart_item (quantity integer not null, subtotal numeric(38,2), unit_price numeric(38,2), cart_id bigint, id bigint generated by default as identity, menu_item_id bigint, primary key (id));
create table customer (id bigint generated by default as identity, email varchar(255) unique, name varchar(255), password varchar(255), phone varchar(255), role varchar(255), primary key (id));
create table delivery (assigned_at timestamp(6) with time zone, created_at timestamp(6) with time zone, delivered_at timestamp(6) with time zone, driver_id bigint, id bigint generated by default as identity, order_id bigint unique, out_for_delivery_at timestamp(6) with time zone, picked_up_at timestamp(6) with time zone, updated_at timestamp(6) with time zone, version bigint, driver_name varchar(255), driver_phone varchar(255), status varchar(255) check (status in ('AVAILABLE','ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')), primary key (id));
create table delivery_status_history (changed_at timestamp(6) with time zone, delivery_id bigint, id bigint generated by default as identity, user_id bigint, new_status varchar(255) check (new_status in ('AVAILABLE','ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')), previous_status varchar(255) check (previous_status in ('AVAILABLE','ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')), reason varchar(255), user_role varchar(255), primary key (id));
create table menu_item (available boolean not null, price numeric(38,2), id bigint generated by default as identity, restaurant_id bigint, description varchar(255), image_url varchar(255), name varchar(255), primary key (id));
create table order_item (quantity integer not null, subtotal numeric(38,2), unit_price numeric(38,2), id bigint generated by default as identity, menu_item_id bigint, order_id bigint, menu_item_name varchar(255), primary key (id));
create table orders (total_amount numeric(38,2), created_at timestamp(6) with time zone, customer_id bigint, id bigint generated by default as identity, restaurant_id bigint, status varchar(255) check (status in ('CREATED','PAYMENT_PENDING','PAID','CONFIRMED','RESTAURANT_ACCEPTED','PREPARING','READY_FOR_PICKUP','DRIVER_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','PAYMENT_FAILED','CANCELLED','REFUNDED')), primary key (id));
create table order_status_history (changed_by_user_id bigint, id bigint generated by default as identity, order_id bigint, timestamp timestamp(6) with time zone, new_status varchar(255) check (new_status in ('CREATED','PAYMENT_PENDING','PAID','CONFIRMED','RESTAURANT_ACCEPTED','PREPARING','READY_FOR_PICKUP','DRIVER_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','PAYMENT_FAILED','CANCELLED','REFUNDED')), previous_status varchar(255) check (previous_status in ('CREATED','PAYMENT_PENDING','PAID','CONFIRMED','RESTAURANT_ACCEPTED','PREPARING','READY_FOR_PICKUP','DRIVER_ASSIGNED','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','PAYMENT_FAILED','CANCELLED','REFUNDED')), reason varchar(255), primary key (id));
create table password_reset_token (customer_id bigint unique, expiry_date timestamp(6), id bigint generated by default as identity, token varchar(255), primary key (id));
create table payment (amount numeric(38,2), created_at timestamp(6) with time zone, id bigint generated by default as identity, order_id bigint, version bigint, razorpay_order_id varchar(255), razorpay_payment_id varchar(255), status varchar(255) check (status in ('PENDING','SUCCESS','FAILED')), primary key (id));
create table restaurant (delivery_radius float(53), latitude float(53), longitude float(53), rating float(53) not null, created_at timestamp(6) with time zone, id bigint generated by default as identity, owner_id bigint, reviewed_at timestamp(6) with time zone, reviewed_by bigint, address varchar(255), area varchar(255), city varchar(255), cover_image_url varchar(255), cuisine varchar(255), location varchar(255), name varchar(255), opening_hours varchar(255), rejection_reason varchar(255), status varchar(255) check (status in ('PENDING_APPROVAL','APPROVED','REJECTED','SUSPENDED')), primary key (id));
create table restaurant_staff_profile (approved_at timestamp(6), created_at timestamp(6), id bigint generated by default as identity, restaurant_id bigint, user_id bigint, approval_status varchar(255) check (approval_status in ('PENDING_APPROVAL','APPROVED','REJECTED')), primary key (id));
create table restaurant_invitation (created_at timestamp(6) with time zone, created_by bigint, id bigint generated by default as identity, restaurant_id bigint, code varchar(255), primary key (id));
create table restaurant_join_request (created_at timestamp(6) with time zone, id bigint generated by default as identity, restaurant_id bigint, user_id bigint, status varchar(255) check (status in ('PENDING_APPROVAL','APPROVED','REJECTED')), primary key (id));
create index idx_delivery_driver_id on delivery (driver_id);
create index idx_delivery_status on delivery (status);
create index idx_order_customer_id on orders (customer_id);
create index idx_order_restaurant_id on orders (restaurant_id);
create index idx_order_status on orders (status);
create index idx_restaurant_lat_lng on restaurant (latitude, longitude);
create index idx_restaurant_city on restaurant (city);
create index idx_restaurant_status on restaurant (status);
create index idx_restaurant_name on restaurant (name);
create index idx_restaurant_cuisine on restaurant (cuisine);
alter table if exists password_reset_token add constraint FK9o3gtqf2ug7wjjxb4pjf7bxak foreign key (customer_id) references customer;
